def obtener_logo_bytes() -> bytes:
    """Devuelve los bytes PNG del escudo oficial UNJBG desde archivo o Base64 embebido."""
    ruta_logo = INSTITUCION["logo_path"]
    if os.path.exists(ruta_logo):
        with open(ruta_logo, "rb") as f:
            return f.read()
    return base64.b64decode(LOGO_UNJBG_BASE64)


def limpiar_prefijo_lista(texto: str) -> str:
    """Elimina numeración o viñetas manuales al inicio (ej. '1. ', '2) ', '- ', '• ') para evitar '1. 1.' en Word."""
    if not texto:
        return ""
    limpio = re.sub(r"^\s*(?:[\-\*\•\–\—]|\(?\d+[\.\)\-\:])\s+", "", texto.strip())
    return limpio.strip()


def limpiar_texto_placeholder(texto: str) -> str:
    """Si el texto conserva marcadores de plantilla entre corchetes o está vacío, devuelve cadena vacía."""
    if not texto:
        return ""
    t = texto.strip()
    placeholders_conocidos = {
        "Apellidos y Nombres - Código Universitario",
        "[Facultad correspondiente]",
        "[Ingeniería Ambiental / Física / etc.]",
        "[Nombre de la práctica]",
        "[Grado y Nombre]",
        "[ ]",
        "Relación experimental entre [Magnitud Y (unidad)] y [Magnitud X (unidad)]",
        "Nota. Ajuste lineal por mínimos cuadrados y = mx + b, R² = ...",
    }
    if t in placeholders_conocidos:
        return ""
    return t


def calcular_regresion_lineal(x_vals: list, y_vals: list) -> dict:
    """Calcula ajuste lineal y = m*x + b por mínimos cuadrados con incertezas estándar."""
    n = len(x_vals)
    if n < 3 or n != len(y_vals):
        raise ValueError("Se necesitan al menos 3 pares de datos (X, Y) con la misma cantidad de elementos.")
    sx = sum(x_vals)
    sy = sum(y_vals)
    sxx = sum(x * x for x in x_vals)
    syy = sum(y * y for y in y_vals)
    sxy = sum(x * y for x, y in zip(x_vals, y_vals))
    denom = n * sxx - sx * sx
    if abs(denom) < 1e-15:
        raise ValueError("Los valores de X no pueden ser todos iguales.")

    m = (n * sxy - sx * sy) / denom
    b = (sy * sxx - sx * sxy) / denom

    residuos = [y - (m * x + b) for x, y in zip(x_vals, y_vals)]
    sr2 = sum(r * r for r in residuos) / (n - 2)
    sr = math.sqrt(max(0.0, sr2))
    dm = sr * math.sqrt(n / denom)
    db = sr * math.sqrt(sxx / denom)

    ss_tot = syy - (sy * sy) / n
    ss_res = sum(r * r for r in residuos)
    r2 = 1.0 - (ss_res / ss_tot) if abs(ss_tot) > 1e-15 else 1.0

    return {"n": n, "m": m, "dm": dm, "b": b, "db": db, "r2": r2}


