            c["docente"] = st.text_input("Docente (opcional):", value=c["docente"], placeholder="Ej. Dr. Juan Pérez Mamani")
            c["fechaEjecucion"] = st.text_input("Fecha de ejecución (opcional):", value=c["fechaEjecucion"], placeholder="Ej. 18/11/2026")

            col_f1, col_f2, col_f3 = st.columns(3)
