        bloques_caratula.append('<div style="text-align:left; max-width:600px; margin: 0 auto; line-height:1.7;">')
        if c["tituloPractica"].strip():
            bloques_caratula.append(f'<p><strong>Título de la práctica:</strong> {c["tituloPractica"].strip()}</p>')
        autores_prev = [a.strip() for a in datos["autores"] if a.strip()]
